#nullable enable

using Drafting.Contracts;
using Drafting.Views;
using Marten;
using Shouldly;
using Xunit;

namespace Drafting.IntegrationTests.Slices.Drafting;

/// <summary>
/// Generated from the model's GWT cells, NOT from the implementation — which is the only reason
/// these tests mean anything. Pattern: view. Status: ready.
/// LIVE: this slice is claimed, so every test here must pass.
/// Owned by backend-agent.
///
/// GIVEN/THEN, NOT GIVEN/WHEN/THEN — there is no WHEN and inventing one would be wrong. A read model
/// only ever reads events that already exist, so no command belongs in the middle. Understanding
/// EventSourcing ch. 3: "you typically do not use GWTs but GTs (Given - Then)."
///
/// So the shape of every test here is: append the GIVEN straight to the stream, then assert the row.
/// Not through an endpoint — this model draws no read endpoint for MyDrafts, and the screen that reads
/// it is the frontend's half of revise-subject. The document IS the contract being specified.
/// </summary>
public sealed class MyDraftsTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private const string OriginalSubject = "Original subject";
    private const string RevisedSubject = "A better subject";
    private const string Body = "The body, which no revision here ever mentions.";

    /// <summary>THEN: the rows this view holds, so a test can assert HOW MANY as well as which.</summary>
    private async Task<IReadOnlyList<MyDrafts>> Rows()
    {
        await using var session = Store.QuerySession();
        return await session.Query<MyDrafts>().OrderBy(x => x.Subject).ToListAsync();
    }

    // a drafted email appears in my drafts
    //   GIVEN EmailDrafted
    //   THEN  MyDrafts
    //   (no WHEN: this is a GIVEN/THEN. Append the GIVEN, then assert the read model through its endpoint.)
    [Fact]
    public async Task ADraftedEmailAppearsInMyDrafts()
    {
        await Given(SeedData.EmailId, new EmailDrafted(
            SeedData.EmailId, "someone@example.com", OriginalSubject, Body, SeedData.SeededAt));

        var row = (await Rows()).ShouldHaveSingleItem();

        // The document id IS the emailId — no prefix, no surrogate. That equality is what lets
        // [WriteAggregate] find the stream from a route argument in revise-subject, and it is why the
        // view can be loaded by the id a screen already has.
        row.Id.ShouldBe(SeedData.EmailId);
        row.EmailId.ShouldBe(SeedData.EmailId);
        row.To.ShouldBe("someone@example.com");
        row.Subject.ShouldBe(OriginalSubject);
        row.Body.ShouldBe(Body);
    }

    // a revised subject replaces the old one
    //   GIVEN EmailDrafted, SubjectRevised
    //   THEN  MyDrafts
    //   (no WHEN: this is a GIVEN/THEN. Append the GIVEN, then assert the read model through its endpoint.)
    [Fact]
    public async Task ARevisedSubjectReplacesTheOldOne()
    {
        await Given(SeedData.EmailId,
            new EmailDrafted(SeedData.EmailId, "someone@example.com", OriginalSubject, Body, SeedData.SeededAt),
            new SubjectRevised(SeedData.EmailId, RevisedSubject, SeedData.SeededAt.AddHours(1)));

        // TWO events, ONE row. Asserting the COUNT is the whole content of this test: a fold that
        // treated a revision as a new thing would leave two rows, both plausible, and an assertion that
        // only loaded by id would pass anyway. This is the delete-vs-upsert question made assertable.
        var row = (await Rows()).ShouldHaveSingleItem();

        row.Subject.ShouldBe(RevisedSubject);
        row.Subject.ShouldNotBe(OriginalSubject);   // REPLACED, not accumulated — MyDrafts keeps no history
    }

    // revising the subject leaves the body alone
    //   GIVEN EmailDrafted, SubjectRevised
    //   THEN  MyDrafts
    //   (no WHEN: this is a GIVEN/THEN. Append the GIVEN, then assert the read model through its endpoint.)
    //
    // THE VALUABLE ONE, and it specifies what the view does NOT change.
    //
    // SubjectRevised carries emailId, subject, revisedAt — and no body and no recipient. So a fold
    // written as "rebuild the row from the latest event", which is the obvious and wrong way to write a
    // projection, blanks both. Nothing else notices: the row still exists, the subject is right, the
    // count is one, and the screen that displays emailId/to/subject does not even read the body.
    //
    // The information-completeness check cannot catch it either. It asks whether every attribute of the
    // view is SUPPLIED by some connected event, and EmailDrafted supplies body — so the model is
    // complete and the fold is still broken. "Which event supplies it" is a question only a fold answers.
    [Fact]
    public async Task RevisingTheSubjectLeavesTheBodyAlone()
    {
        await Given(SeedData.EmailId,
            new EmailDrafted(SeedData.EmailId, "someone@example.com", OriginalSubject, Body, SeedData.SeededAt),
            new SubjectRevised(SeedData.EmailId, RevisedSubject, SeedData.SeededAt.AddHours(1)));

        var row = (await Rows()).ShouldHaveSingleItem();

        row.Body.ShouldBe(Body);
        row.To.ShouldBe("someone@example.com");

        // And the revision did land, so this is not passing because nothing happened at all.
        row.Subject.ShouldBe(RevisedSubject);
    }
}
